import { readFile, writeFile } from "node:fs/promises";
const types = await readFile("src/lib/federations.ts", "utf8");
const handler = (
  await readFile("supabase/functions/federation-records/index.ts", "utf8")
).replace(/^import\s*\{[\s\S]*?\}\s*from\s*["'][^"']+["'];\s*/, "");
await writeFile(
  "supabase/federation-records-dashboard.ts",
  "// Generated by npm run prepare:federations. Paste this entire file into the Supabase Edge Function editor.\n" +
    types +
    "\n" +
    handler,
);
console.log(
  "Ready: supabase/federation-records-dashboard.ts (no imports or secrets required).",
);
